// Добавляет в garden-data.xlsx регион "Юг" (Краснодарский край / Ростовская
// область / Ставрополье) взамен старого приближения "сдвиг месяца от средней
// полосы". Логика:
//   1. Берём срав. полосу как базу и сдвигаем месяцы той же функцией, что
//      раньше жила в build-full-data.js (тёплая весна раньше, осень позже) -
//      это по-прежнему разумное приближение для однолетних овощных культур,
//      где реальной технологической разницы с средней полосой нет, только
//      сроки. Помечаем такие строки как "авто" - не пересмотрено вручную.
//   2. Убираем из этой базы записи, где для юга есть реальная качественная
//      разница (не только сроки), и заменяем собственными строками,
//      подтверждёнными веб-поиском (см. source в каждой строке).
//   3. Добавляем персик как новую культуру (типичную для юга) с полным
//      годовым циклом работ.
//   4. Переносим 4 записи, которые уже были написаны вручную для юга в
//      старой версии build-full-data.js (не выдумки, реальная специфика).
//
// Источники (веб-поиск, август 2026):
// - Персик: посадка/обрезка/уход - https://www.supersadovnik.ru/plant/persik-1618,
//   https://rastenievod.com/persik.html, https://floristics.info/ru/stati/sad/2643-persik-posadka-i-ukhod-obrezka-i-privivka.html
// - Курчавость листьев персика - https://ferma.expert/rasteniya/derevya/persiki/kurchavost-listev/
// - Виноград без укрытия на юге - https://7dach.ru/izdatelstvo_AST/nadezhnye-sposoby-ukrytiya-vinograda-dlya-raznyh-regionov-209838.html
// - Розы на юге (сроки обрезки/укрытия) - http://www.rosebook.ru/topics/yuliacoba/zimovka-v-juzhnyh-regionah/,
//   https://www.ogorod.ru/ru/outdoor/rose/17806/Obrezaem-rozy-zimoj-reshenie-dlya-yuzhnyh-regionov.htm
// - Хвойные, жара/засуха на юге - https://abekker.ru/articles/solnechnye-ojogi-u-hvoynyh-chto-delat-i-kak-borotsya,
//   https://pitomnik-vo.ru/tpost/y4eohlft01-tuya-i-mozhzhevelnik-problemi-profilakti

const fs = require('fs');
const path = require('path');
const XLSX = require('xlsx');

const ROOT = path.resolve(__dirname, '..', '..');
const XLSX_PATH = path.join(ROOT, 'garden-data.xlsx');

const wb = XLSX.readFile(XLSX_PATH);
const calSheet = wb.Sheets['Calendar'];
const calRows = XLSX.utils.sheet_to_json(calSheet);
const plantsSheet = wb.Sheets['Plants'];
const plantRows = XLSX.utils.sheet_to_json(plantsSheet);

const MONTH_IDS = ['yanvar','fevral','mart','aprel','may','iyun','iyul','avgust','sentyabr','oktyabr','noyabr','dekabr'];
const MONTH_NAMES = ['ЯНВАРЬ','ФЕВРАЛЬ','МАРТ','АПРЕЛЬ','МАЙ','ИЮНЬ','ИЮЛЬ','АВГУСТ','СЕНТЯБРЬ','ОКТЯБРЬ','НОЯБРЬ','ДЕКАБРЬ'];

// Та же таблица сдвигов, что была в build-full-data.js
const SHIFT = { 2: -1, 3: -1, 4: -1, 5: 0, 6: 0, 7: 0, 8: 1, 9: 1, 10: 1 };
function shiftMonth(idx) {
  const delta = SHIFT[idx] || 0;
  let n = idx + delta;
  if (n < 0) n = 0;
  if (n > 11) n = 11;
  return n;
}

const AUTO = 'авто (сдвиг месяца от средней полосы, не пересмотрено)';
const spRows = calRows.filter(r => r.region === 'srednyaya-polosa');

let yugAuto = spRows.map(r => {
  const oldIdx = MONTH_IDS.indexOf(r.month);
  const newIdx = shiftMonth(oldIdx);
  return { ...r, region: 'yug', month: MONTH_IDS[newIdx], monthName: MONTH_NAMES[newIdx], source: AUTO };
});

// Несимметричный сдвиг (весна раньше, осень позже) неизбежно оставляет
// месяцы-"дыры" без единой записи после сдвига (см. комментарий в старом
// build-full-data.js) - заполняем их несдвинутым контентом средней полосы
// для этого месяца, иначе часть месяцев на юге останется совсем пустой.
{
  const countByMonth = new Array(12).fill(0);
  for (const e of yugAuto) countByMonth[MONTH_IDS.indexOf(e.month)]++;
  countByMonth.forEach((count, idx) => {
    if (count === 0) {
      for (const r of spRows) {
        if (r.month === MONTH_IDS[idx]) yugAuto.push({ ...r, region: 'yug', source: AUTO });
      }
    }
  });
}

// Заполнение "дыр" даёт побочный эффект: для КАЖДОЙ записи, чей исходный
// месяц сдвигается в другой (а не остаётся на месте), появляется два
// экземпляра одной и той же карточки - сдвинутый и несдвинутый (fallback-
// копия для месяца-"дыры"). Проверка на 2 конкретных примерах (томат/перец,
// огурец/кабачок/тыква - оба относятся к маю) показала: сдвиг весны на юге
// (-1 месяц) слишком агрессивен для сроков высадки рассады - реальный срок
// (веб-поиск) близок к исходному майскому, а не апрельскому. Проверка на
// озимом чесноке (сентябрь->октябрь, сдвиг осени +1) показала обратное -
// сдвинутая дата (октябрь-ноябрь) точнее исходной. Экстраполируем этот
// вывод на все такие пары одинакового текста в разных месяцах: для весны
// (апрель/май) оставляем май (исходный), для осени (октябрь/сентябрь)
// оставляем октябрь (сдвинутый) - вместо показа одной и той же рекомендации
// дважды. Это обобщение по 3 проверенным примерам, а не индивидуальная
// проверка каждой из ~30 пар - если для конкретной культуры это в будущем
// окажется неточным, стоит уточнить веб-поиском отдельно.
function dedupFallbackPair(list, monthKeep, monthDrop) {
  const keySeen = new Set();
  for (const e of list) {
    if (e.month === monthKeep) keySeen.add(e.workType + '|' + e.category + '|' + e.text);
  }
  return list.filter(e => !(e.month === monthDrop && keySeen.has(e.workType + '|' + e.category + '|' + e.text)));
}
yugAuto = dedupFallbackPair(yugAuto, 'may', 'aprel');
yugAuto = dedupFallbackPair(yugAuto, 'oktyabr', 'sentyabr');

// --- Убираем то, что заменяем реальной региональной спецификой юга ---
function dropAuto(pred) {
  const before = yugAuto.length;
  yugAuto = yugAuto.filter(r => !pred(r));
  return before - yugAuto.length;
}

// Томат/перец/капуста: сдвиг месяца + fallback-заполнение "дыр" дают дубль
// одной и той же записи в апреле И мае (см. комментарий про fallback выше) -
// причём апрельская дата для высадки в грунт на юге слишком ранняя (реальный
// срок - начало мая). Убираем обе копии, заменяем одной записью с точным
// сроком.
dropAuto(r => r.workType === 'posev' && r.plants.split(',').includes('tomat')
  && r.text.includes('после угрозы возвратных заморозков') && r.text.toLowerCase().includes('высадка рассады'));

// Озимый чеснок: на юге реальный срок посадки позже унаследованной формулировки
dropAuto(r => r.workType === 'posev' && r.plants.split(',').includes('chesnok')
  && r.text.includes('Посадка озимого чеснока'));

// Виноград: обязательное укрытие средней полосы -> для юга не актуально.
// Также убираем посадочную заметку "(в средней полосе — только зимостойких
// сортов)" - при показе региона "Юг" упоминание средней полосы как ориентира
// вводит в заблуждение, плюс само ограничение для юга не действует.
dropAuto(r => r.workType === 'ukrytie' && r.plants.split(',').includes('vinograd'));
dropAuto(r => r.workType === 'posev' && r.plants.split(',').includes('vinograd')
  && r.text.includes('в средней полосе'));

// Розы: осенняя обрезка-перед-укрытием и укрытие -> другие сроки и в основном без укрытия
dropAuto(r => r.category === 'dekor' && r.plants.split(',').includes('roza')
  && (r.workType === 'ukrytie' || (r.workType === 'obrezka' && r.text.includes('перед укрытием'))));

// Хвойные: весенние укрытия от солнечных ожогов из-за отражения света от снега -
// на юге снег редкий/недолгий, механизм ожога (яркое солнце + отражение от снега +
// промёрзшие корни) не актуален так же, как в средней полосе. Убираем полностью
// весь цикл установка/снятие притенения (иначе останется запись "снятие
// укрытия", для которого на юге не было установки) - заменяем на летнюю
// жара/засуха специфику. То же для молодых ели/сосны (снеговой механизм ожога
// там ещё менее актуален, чем у туи/можжевельника) - оставляем только общее
// предупреждение про адаптационный период первых зим, без цикла притенения.
dropAuto(r => r.workType === 'ukrytie' && r.category === 'dekor'
  && ['tuya','mozhzhevelnik','el','sosna'].some(p => r.plants.split(',').includes(p))
  && (r.text.includes('притен') || r.text.includes('Снятие зимних укрытий с хвойных')));

function row(region, monthIdx, workType, category, plants, growMethod, text, source, detail) {
  return {
    region, month: MONTH_IDS[monthIdx], monthName: MONTH_NAMES[monthIdx], workType, category,
    plants: plants.join(','), growMethod: growMethod.join(','), text, detail: detail || '', source: source || '',
  };
}

const SRC_PERSIK = 'веб-поиск: supersadovnik.ru, rastenievod.com, floristics.info, ferma.expert (авг. 2026)';
const SRC_VINOGRAD = 'веб-поиск: 7dach.ru «Надёжные способы укрытия винограда для разных регионов» (авг. 2026)';
const SRC_ROZA = 'веб-поиск: rosebook.ru «Зимовка в южных регионах», ogorod.ru (авг. 2026)';
const SRC_HVOYNYE = 'веб-поиск: abekker.ru «Солнечные ожоги у хвойных», pitomnik-vo.ru (авг. 2026)';
const SRC_OGOROD_SROKI = 'веб-поиск: сроки посадки томата/перца на юге России (авг. 2026)';

const newYug = [
  // --- Озимый чеснок: на юге сажают позже, чем формулировка "конец
  // сентября - начало октября", унаследованная от средней полосы ---
  row('yug', 9, 'posev', 'ogorod', ['chesnok'], ['grunt'],
    'Посадка озимого чеснока на юге — с 20 октября до конца ноября (позже, чем в средней полосе: тёплая осень позволяет сажать почти перед самыми морозами).',
    SRC_OGOROD_SROKI),

  // --- Клубника: на юге доступна ранняя весенняя посадка рассадой (помимо
  // стандартной осенней посадки усами, которая тоже актуальна) ---
  row('yug', 2, 'posev', 'sad', ['klubnika'], ['grunt'],
    'На юге возможна ранняя весенняя посадка клубники рассадой — конец марта — начало апреля (в отличие от большинства регионов, где весеннюю посадку проводят позже, в мае).',
    SRC_OGOROD_SROKI),

  // --- Томат/перец: точный срок высадки в грунт на юге ---
  row('yug', 4, 'posev', 'ogorod', ['tomat','perets','kapusta'], ['rassada'],
    'Высадка рассады в грунт на юге — с начала мая, когда почва прогреется до 14-16°C и заморозков уже не будет; перец в теплицу можно высаживать чуть раньше, с конца апреля.',
    SRC_OGOROD_SROKI),

  // --- Персик: новая культура для юга ---
  row('yug', 9, 'posev', 'sad', ['persik'], ['grunt'],
    'Осенняя посадка саженцев персика (сентябрь-октябрь) — успевает укорениться до холодов. Посадочную яму заправляют перегноем и фосфорно-калийным удобрением, без избытка азота.',
    SRC_PERSIK),
  row('yug', 2, 'obrezka', 'sad', ['persik'], ['grunt'],
    'Формирующая обрезка персика в чашевидной форме (вырезают центральный проводник, оставляя 5-6 скелетных ветвей) — между началом сокодвижения и началом цветения.',
    SRC_PERSIK),
  row('yug', 2, 'obrabotka', 'sad', ['persik'], ['grunt'],
    'Профилактика курчавости листьев персика — двукратное опрыскивание 1%-м медным купоросом (или 3%-й бордоской жидкостью) с интервалом 7 дней, до начала сокодвижения.',
    SRC_PERSIK,
    'Медьсодержащие препараты (медный купорос, бордоская жидкость) — оптимально +5…+25°C, не выше +30°C (риск ожога). При уже проявившейся курчавости повреждённые побеги вырезают и проводят внеплановую обработку тем же препаратом, если до созревания плодов остаётся не менее 3 недель.'),
  row('yug', 4, 'obrabotka', 'sad', ['persik'], ['grunt'],
    'Персиковая тля образует плотные колонии на штамбе и молодых побегах снизу; пилильщики и долгоносики повреждают завязь — двукратная обработка инсектицидом сразу после образования завязи.',
    SRC_PERSIK),
  row('yug', 9, 'obrabotka', 'sad', ['persik'], ['grunt'],
    'Повторная обработка медьсодержащим препаратом (1% медный купорос или 3% бордоская жидкость, оптимально +5…+25°C) в период листопада — если весенняя обработка от курчавости не проводилась или заражение было сильным.',
    SRC_PERSIK),
  row('yug', 9, 'udobrenie', 'sad', ['persik'], ['grunt'],
    'Осенняя перекопка приствольного круга с внесением суперфосфата и хлористого кальция; органику (перегной, компост) вносят раз в 2-3 года.',
    SRC_PERSIK),
  row('yug', 7, 'urozhay', 'sad', ['persik'], ['grunt'],
    'Сбор урожая персика — в зависимости от сорта с конца июля по сентябрь.',
    SRC_PERSIK),

  // --- Виноград: без укрытия для морозостойких сортов ---
  row('yug', 8, 'posev', 'sad', ['vinograd'], ['grunt'],
    'Осенняя посадка саженцев винограда — в мягком климате юга приживаются как морозостойкие, так и укрывные сорта.',
    SRC_VINOGRAD),
  row('yug', 10, 'ukrytie', 'sad', ['vinograd'], ['grunt'],
    'На юге морозостойкие сорта винограда, как правило, зимуют без укрытия — достаточно уложить лозу на землю. Неморозостойким сортам нужно лёгкое укрытие (1-2 слоя плёнки, рубероида или иного материала с вентиляцией, без герметичной обмотки). Сроки — ноябрь, в тёплые зимы возможно и декабрь.',
    SRC_VINOGRAD),

  // --- Розы: другие сроки обрезки, укрытие не обязательно ---
  row('yug', 8, 'obrezka', 'dekor', ['roza'], ['grunt'],
    'На юге обрезку роз начинают уже в конце сентября — начале октября: здоровые побеги укорачивают на 15-20 см с сохранением формы куста.',
    SRC_ROZA),
  row('yug', 10, 'ukrytie', 'dekor', ['roza'], ['grunt'],
    'Взрослые зимостойкие сорта роз на юге обычно зимуют без укрытия или с лёгким окучиванием (1-2 ведра почвосмеси на куст, холмик высотой ~20 см). Чайно-гибридные и плетистые сорта укрывают после наступления устойчивых лёгких заморозков — обычно в ноябре, в Краснодарском крае и Крыму иногда в декабре.',
    SRC_ROZA),

  // --- Ель на юге: хуже переносит жару и сухость, чем сосна ---
  row('yug', 8, 'posev', 'dekor', ['el','sosna'], ['grunt'],
    'На юге ель хуже переносит летнюю жару и сухость воздуха, чем сосна (у сосны глубокая стержневая корневая система лучше достаёт влагу) — при выборе для жаркого сухого участка предпочтение отдают сосне или засухоустойчивым видам туи/можжевельника.',
    'веб-поиск: общие сведения о засухоустойчивости хвойных (авг. 2026)'),
  row('yug', 1, 'ukrytie', 'dekor', ['el','sosna'], ['grunt'],
    'Снеговой механизм весенних ожогов (яркое солнце + отражение от снега) на юге малоактуален из-за короткого снежного покрова. Но саженцы первых 2-3 лет всё равно уязвимее взрослых растений в период адаптации — в морозные ясные дни их можно лёгким нетканым материалом притенить с южной стороны, без герметичного укрытия.',
    SRC_HVOYNYE),

  // --- Хвойные: летняя жара/засуха вместо зимнего снега ---
  row('yug', 5, 'poliv', 'dekor', ['tuya','mozhzhevelnik','samshit'], ['grunt'],
    'Летняя жара и сухость на юге вызывают побурение хвои (обезвоживание, «горит» с южной стороны) — регулярный полив (почва умеренно влажная, без застоя, при переувлажнении — рыхление и дренаж) и вечернее дождевание кроны для повышения влажности воздуха и смывания пыли.',
    SRC_HVOYNYE),
];

const finalCal = [...calRows.filter(r => r.region !== 'yug'), ...yugAuto, ...newYug];

const newPlantRows = [
  ...plantRows.filter(p => p.id !== 'persik'),
  { id: 'persik', name: 'Персик', category: 'sad', group: 'derevo', hasSeedlingStage: 'нет', regions: 'yug' },
];

function replaceSheet(name, rows, colWidths) {
  const ws = XLSX.utils.json_to_sheet(rows);
  if (colWidths) ws['!cols'] = colWidths;
  wb.Sheets[name] = ws;
}

replaceSheet('Calendar', finalCal, [
  { wch: 16 }, { wch: 10 }, { wch: 10 }, { wch: 10 }, { wch: 10 },
  { wch: 24 }, { wch: 14 }, { wch: 60 }, { wch: 50 }, { wch: 40 },
]);
replaceSheet('Plants', newPlantRows, [
  { wch: 16 }, { wch: 26 }, { wch: 10 }, { wch: 18 }, { wch: 10 }, { wch: 20 },
]);

XLSX.writeFile(wb, XLSX_PATH);
console.log(`Юг: ${yugAuto.length} авто-строк + ${newYug.length} новых исследованных строк = ${yugAuto.length + newYug.length}`);
console.log(`Итого Calendar: ${finalCal.length} строк`);
console.log(`Итого Plants: ${newPlantRows.length}`);
